const D = { energy: .6, scale: 1, speed: 1, density: .55, discharge: .5, hue: 205, x: .5, y: .5, style: 'fisk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Meander migration, Ikeda-Parker-Sawai bend theory (simplified) ----------
// Lateral migration at a node = exponentially weighted UPSTREAM curvature, so
// bends both GROW (the bend instability) and TRANSLATE downstream (phase lag).
// When a neck closes on itself the loop is severed -> an oxbow lake is abandoned
// and sinuosity resets. THAT CUTOFF CYCLE is why this never reaches equilibrium.
// Every channel position is printed into a floodplain plate, so the swept belt
// accretes as arcuate scroll bars (Harold Fisk's Mississippi plates) while slow
// overbank burial fades the oldest scars to ghosts -> bounded memory, endless change.
const BW = 768, BH = 432;

const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> : an arithmetic fold would cap at .5
}
function vn(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
  const a = hsh(ix, iy), b = hsh(ix + 1, iy), c = hsh(ix, iy + 1), d2 = hsh(ix + 1, iy + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d2) * u * v;
}
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- style: palette + rendering philosophy ---------------------------------
const st = P.style;
const rot = h => (((h + (P.hue - 205)) % 360) + 360) % 360;
let base, waterC, inkC, barC, belts, grainAmt, lineOnly;
if (st === 'satellite') {           // false-colour NIR: vegetation dark red, water near-black, bars white
  base = [352, 54, 24]; belts = [[10, 52, 32], [24, 46, 40], [350, 48, 27], [35, 38, 46], [2, 46, 35], [16, 40, 43]];
  waterC = [rot(200), 55, 13]; barC = [45, 10, 88]; inkC = [0, 0, 6]; grainAmt = 10; lineOnly = false;
} else if (st === 'survey') {       // aged sepia plate: line over mass, ink hachure, blue water
  base = [40, 30, 62]; belts = [[32, 36, 50], [28, 30, 57], [36, 32, 44], [24, 34, 53], [42, 28, 47], [30, 38, 42]];
  waterC = [rot(205), 62, 42]; barC = [42, 20, 78]; inkC = [28, 44, 16]; grainAmt = 17; lineOnly = true;
} else if (st === 'blueprint') {    // cyanotype schematic: pale drafting lines on prussian ground
  base = [rot(212), 70, 19]; belts = [[rot(196), 34, 58], [rot(186), 26, 70], [rot(206), 40, 50], [rot(176), 22, 78], [rot(216), 36, 56], [rot(190), 30, 64]];
  waterC = [0, 0, 96]; barC = [rot(190), 18, 86]; inkC = [rot(190), 28, 90]; grainAmt = 8; lineOnly = true;
} else {                            // fisk (default): alluvial plate, historic belts in plate inks
  base = [34, 44, 38]; belts = [[178, 54, 58], [38, 62, 64], [350, 46, 58], [86, 46, 50], [210, 40, 56], [292, 38, 52]];
  waterC = [rot(206), 66, 29]; barC = [44, 36, 74]; inkC = [0, 0, 12]; grainAmt = 14; lineOnly = false;
}

// ---- buffers ---------------------------------------------------------------
if (!S.fp) {
  S.fp = createGraphics(BW, BH); S.fp.pixelDensity(1);
  S.fp.colorMode(HSB, 360, 100, 100, 100); S.fp.noStroke();
  S.styleUsed = null; S.seedUsed = null;
}
if (!S.grain || S.grainSeed !== sd) {
  S.grainSeed = sd;
  const g = S.grain || (S.grain = createGraphics(256, 144));
  g.pixelDensity(1); g.loadPixels();
  for (let i = 0; i < 256 * 144; i++) {
    const v = 206 + hsh(i % 256, (i / 256) | 0) * 49;
    const o = i * 4; g.pixels[o] = v; g.pixels[o + 1] = v; g.pixels[o + 2] = v; g.pixels[o + 3] = 255;
  }
  g.updatePixels();
}
if (!S.vig || S.vigKey !== width + 'x' + height) {
  const gd = drawingContext.createRadialGradient(width / 2, height / 2, Math.min(width, height) * 0.26,
                                                 width / 2, height / 2, Math.max(width, height) * 0.74);
  gd.addColorStop(0, 'rgba(0,0,0,0)'); gd.addColorStop(1, 'rgba(0,0,0,0.40)');
  S.vig = gd; S.vigKey = width + 'x' + height;
}

// ---- (re)seed the reach ----------------------------------------------------
function clearPlate() { S.fp.push(); S.fp.noStroke(); S.fp.fill(base[0], base[1], base[2], 100); S.fp.rect(0, 0, BW, BH); S.fp.pop(); }
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed; S.styleUsed = st;
  S.ds = 0.0105;
  S.rx = []; S.ry = [];
  const n0 = Math.round(1 / S.ds);
  for (let i = 0; i <= n0; i++) {
    const u = i / n0;
    S.rx.push(u);
    S.ry.push(0.5 + 0.05 * Math.sin(u * Math.PI * 5.3 + fr(1) * 6.283)
                  + 0.026 * Math.sin(u * Math.PI * 12.7 + fr(2) * 6.283)
