}
if (S.styleUsed !== st) { S.styleUsed = st; clearPlate(); }   // replate in the new inks

// ---- flood stage: incommensurate real-time sines (never re-phases at 8s) ----
const flood = 0.5 + 0.5 * (0.55 * Math.sin(K.t * 0.041) + 0.31 * Math.sin(K.t * 0.0934 + 1.9) + 0.14 * Math.sin(K.t * 0.1571 + 0.4));
