const spd = 0.35 + P.speed * 0.95;
const dts = Math.min(0.05, (typeof deltaTime === 'number' ? deltaTime : 16.7) / 1000);

// ---- one migration step ----------------------------------------------------
function step(rate) {
  const n = S.rx.length; if (n < 12) return;
  const cur = S.cur || (S.cur = []); cur.length = n;
  for (let i = 1; i < n - 1; i++) {
    const ax = S.rx[i] - S.rx[i - 1], ay = S.ry[i] - S.ry[i - 1];
    const bx = S.rx[i + 1] - S.rx[i], by = S.ry[i + 1] - S.ry[i];
    const la = Math.hypot(ax, ay) || 1e-6, lb = Math.hypot(bx, by) || 1e-6;
    const cr = Math.max(-1, Math.min(1, (ax * by - ay * bx) / (la * lb)));
    cur[i] = Math.asin(cr) / ((la + lb) * 0.5);
  }
  cur[0] = 0; cur[n - 1] = 0;
  const nrx = S.nrx || (S.nrx = []), nry = S.nry || (S.nry = []);
  nrx.length = n; nry.length = n;
  for (let i = 0; i < n; i++) { nrx[i] = S.rx[i]; nry[i] = S.ry[i]; }
  for (let i = 1; i < n - 1; i++) {
    // exponentially weighted upstream curvature -> growth + downstream translation
    let s = 0, w = 0;
    for (let k = 0; k < 22; k++) { const j = i - k; if (j < 1) break; const wk = Math.exp(-k * 0.16); s += cur[j] * wk; w += wk; }
    const mig = w > 0 ? s / w : 0;
    const tx = S.rx[i + 1] - S.rx[i - 1], ty = S.ry[i + 1] - S.ry[i - 1];
    const tl = Math.hypot(tx, ty) || 1e-6;
    const nx = ty / tl, ny = -tx / tl;            // outward normal for a positive bend
    const edge = Math.min(1, Math.min(i, n - 1 - i) / 14);           // pinned inlet/outlet
    const er = 0.5 + 1.0 * vn(S.rx[i] * 9 + 3.1, S.ry[i] * 9 - 1.7); // heterogeneous floodplain (clay plugs resist)
    const conf = 1 - 0.92 * Math.max(0, (Math.abs(S.ry[i] - 0.5) - 0.36) / 0.11); // valley confinement (wide enough for loops to close)
    let m = mig * rate * edge * er * Math.max(0.05, conf);
    // CFL clamp: a tight loop reaches curvature ~60, and speed/energy are both
    // poke-able to max — without this the step can exceed node spacing and the
    // polyline turns itself inside out.
    const lim = S.ds * 0.25; if (m > lim) m = lim; else if (m < -lim) m = -lim;
    // Mild centreline smoothing. The flow cannot follow wiggles shorter than the
    // channel width, and without this the bend instability amplifies node-scale
    // noise into runaway length instead of coherent bends.
    const sm = 0.075;
    nrx[i] = S.rx[i] + nx * m + (S.rx[i - 1] + S.rx[i + 1] - 2 * S.rx[i]) * sm;
    nry[i] = S.ry[i] + ny * m + (S.ry[i - 1] + S.ry[i + 1] - 2 * S.ry[i]) * sm;
    if (nry[i] < 0.04) nry[i] = 0.04; else if (nry[i] > 0.96) nry[i] = 0.96;
  }
  for (let i = 0; i < n; i++) { S.rx[i] = nrx[i]; S.ry[i] = nry[i]; }
  // ---- resample to constant node spacing (bends lengthen the reach) --------
  const ds = S.ds, ox2 = [S.rx[0]], oy2 = [S.ry[0]];
  let px = S.rx[0], py = S.ry[0], i2 = 1, acc = 0, guard = 0, capped = false;
  while (i2 < S.rx.length && guard++ < 6000) {
    const dx = S.rx[i2] - px, dy = S.ry[i2] - py, d = Math.hypot(dx, dy);
    if (acc + d >= ds) {
      const nd = (ds - acc) / (d || 1e-9); px += dx * nd; py += dy * nd;
      ox2.push(px); oy2.push(py); acc = 0;
      if (ox2.length > 1100) { capped = true; break; }   // backstop only — cutoffs hold n near ~300
    } else { acc += d; px = S.rx[i2]; py = S.ry[i2]; i2++; }
  }
  // Only re-pin the outlet if we walked the whole reach. Appending it after an
  // early break would stitch a spurious straight bar across the map.
  if (!capped) { ox2.push(S.rx[S.rx.length - 1]); oy2.push(S.ry[S.ry.length - 1]); }
  if (ox2.length > 24) { S.rx = ox2; S.ry = oy2; }
}

// ---- neck cutoff -> oxbow lake ---------------------------------------------
// Scans the WHOLE reach for a neck via a spatial hash (a windowed scan misses
// the long loops, and O(n^2) is too slow once the reach is 500+ nodes). The
// threshold is the channel width — two banks touching IS the cutoff — and it
// grows if the reach ever gets pathologically long, which bounds sinuosity no
// matter how hard speed/energy are poked.
function cutoff(beltHue) {
  const n = S.rx.length; if (n < 30) return false;
  const strain = 1 + Math.max(0, (n - 430) / 430) * 1.6;
  const thr = Math.max(S.ds * 1.55, wsim * 1.9) * strain, t2 = thr * thr;
  const cell = thr;
  const grid = S.grid || (S.grid = new Map()); grid.clear();
  for (let i = 0; i < n; i++) {
    const k = Math.floor(S.rx[i] / cell) * 100003 + Math.floor(S.ry[i] / cell);
    const arr = grid.get(k); if (arr) arr.push(i); else grid.set(k, [i]);
  }
  let bi = -1, bj = -1, bd = 1e9;
  for (let i = 1; i < n - 13; i++) {
    const gx = Math.floor(S.rx[i] / cell), gy = Math.floor(S.ry[i] / cell);
    for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
      const arr = grid.get((gx + a) * 100003 + (gy + b)); if (!arr) continue;
      for (let m = 0; m < arr.length; m++) {
        const j = arr[m];
        if (j - i < 13 || j > n - 2) continue;      // along-channel neighbours aren't a neck
        const dx = S.rx[j] - S.rx[i], dy = S.ry[j] - S.ry[i], d = dx * dx + dy * dy;
        if (d < t2 && d < bd) { bd = d; bi = i; bj = j; }
      }
    }
  }
  if (bi < 0) return false;
  S.ox.push({ x: S.rx.slice(bi, bj + 1), y: S.ry.slice(bi, bj + 1), a: 1, h: beltHue });
  const keep = 3 + Math.round(P.density * 6);
  while (S.ox.length > keep) S.ox.shift();
  S.rx.splice(bi + 1, bj - bi - 1); S.ry.splice(bi + 1, bj - bi - 1);
  return true;
}

// ---- print the current channel into the floodplain plate -------------------
const beltIdx = Math.floor(S.age / S.epochLen);
const bc = belts[((beltIdx % belts.length) + belts.length) % belts.length];
function paintTrace(col, al, wmul) {
  const g = S.fp; g.push(); g.noFill();
  g.stroke(col[0], col[1], col[2], al); g.strokeCap(ROUND); g.strokeJoin(ROUND);
