const wsim = 0.0092 * (0.5 + P.discharge * 1.05) * (0.72 + stage * 0.62);
const rate = 0.000012 * spd * (0.42 + P.energy * 1.15) * (0.55 + stage * 1.15);

// Warm start: run ~1000 steps over the first second so the reach opens at an
// already-mature sinuosity with a couple of cutoff generations printed into the
