if (!lineOnly) paintTrace(barC, 2.0, 0.42);   // point-bar crest inside the belt

// ---- view transform --------------------------------------------------------
const z = Math.max(1, P.scale), hw = 0.5 / z;
const cx = Math.min(1 - hw, Math.max(hw, P.x)), cy = Math.min(1 - hw, Math.max(hw, P.y));
const SX = x => (x - cx) * z * width + width / 2;
const SY = y => (y - cy) * z * height + height / 2;
const AL = P.alpha / 100;

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.fp, 0, 0, width, height, (cx - hw) * BW, (cy - hw) * BH, 2 * hw * BW, 2 * hw * BH);
